import { Mesh, PlaneGeometry, Object3D, Color } from "three/webgpu";
import {
  MeshBasicNodeMaterial,
  MeshStandardNodeMaterial,
  color,
  texture,
  uv,
  mix,
  smoothstep,
  mul,
  vec4,
  add,
  sub,
  float,
} from "three/tsl";
import { gsap } from "gsap";
import { createTextMesh } from "@/text";

/**
 * @typedef {Object} NodeConfig
 * @property {Array<{name:string,params:any}>} cinematicPrimitives
 * @property {Array<string>} textContent
 */

/**
 * @typedef {Object} NodeContext
 * @property {Object} primitives
 * @property {Object} fontAtlas - contains at least a `.texture` (THREE.Texture) property
 */

/**
 * Create a horizontal data ticker ribbon.
 *
 * @param {NodeConfig} config
 * @param {NodeContext} ctx
 * @returns {THREE.Object3D}
 */
export default function createNode(config, ctx) {
  // ----- constants ---------------------------------------------------------
  const PLANE_WIDTH = 7.0; // scene units
  const PLANE_HEIGHT = 0.35; // scene units
  const BACKGROUND_COLOR = "#111117";
  const EDGE_FADE_START = 0.09;
  const EDGE_FADE_END = 0.91;
  const TICK_COLOR = "#ff2a38";
  const TICK_WIDTH = 0.02 * PLANE_WIDTH; // 0.02w
  const TICK_HEIGHT = 0.14 * PLANE_HEIGHT; // 0.14h
  const TICK_GAP = 2 * 0.25; // 2×base unit (0.5 scene units)
  const TEXT_COLOR = "#e8ecf2";
  const TEXT_FONT_SIZE = 13; // px (used by createTextMesh)
  const TEXT_FONT_WEIGHT = 700;

  // ----- container ---------------------------------------------------------
  const root = new Object3D();
  root.position.set(0, 0, 0);
  root.rotation.set(0, 0, 0);
  root.scale.set(1, 1, 1);

  // ----- base plane ---------------------------------------------------------
  const planeGeo = new PlaneGeometry(PLANE_WIDTH, PLANE_HEIGHT);
  const baseMat = new MeshBasicNodeMaterial({
    transparent: true,
    depthWrite: false,
  });

  // background color
  baseMat.colorNode = color(BACKGROUND_COLOR);

  // edge fade mask (alpha)
  const uvNode = uv();
  const fadeLeft = smoothstep(float(0), float(EDGE_FADE_START), uvNode.x);
  const fadeRight = sub(float(1), smoothstep(float(EDGE_FADE_END), float(1), uvNode.x));
  const fadeMask = mul(fadeLeft, fadeRight);
  baseMat.alphaNode = fadeMask;

  const basePlane = new Mesh(planeGeo, baseMat);
  basePlane.renderOrder = 0;
  root.add(basePlane);

  // ----- ticker text --------------------------------------------------------
  // concatenate entries with a separator (two spaces) to give visual breathing
  const tickerString = config.textContent.join("  ");

  // create a mesh that renders the MSDF text; it is a plane that fits the text width
  const textMesh = createTextMesh(tickerString, {
    fontAtlas: ctx.fontAtlas,
    color: TEXT_COLOR,
    fontSize: TEXT_FONT_SIZE,
    fontWeight: TEXT_FONT_WEIGHT,
    lineHeight: 1,
    letterSpacing: 0.06,
    // we want the text to sit slightly in front of the base plane
    zOffset: 0.02,
  });

  // Scale the text mesh to match the ribbon height (0.35 scene units)
  // Assuming the generated mesh has a height of 1 unit, we scale uniformly.
  const textScale = PLANE_HEIGHT / textMesh.geometry.boundingBox.getSize(new THREE.Vector3()).y;
  textMesh.scale.setScalar(textScale);
  textMesh.position.set(0, 0, 0.001); // just above the base plane
  root.add(textMesh);

  // ----- duplicate for seamless loop ----------------------------------------
  const textClone = textMesh.clone();
  // width of the original text plane (after scaling)
  const textWidth = textMesh.geometry.boundingBox.getSize(new THREE.Vector3()).x * textScale;
  textClone.position.set(textWidth, 0, 0.001);
  root.add(textClone);

  // ----- tick marks ---------------------------------------------------------
  // place tick marks between entries; we approximate positions using the known gaps
  const tickGeo = new PlaneGeometry(TICK_WIDTH, TICK_HEIGHT);
  const tickMat = new MeshStandardNodeMaterial({
    transparent: true,
    emissiveNode: color(TICK_COLOR),
    emissiveIntensity: 1.5,
    depthWrite: false,
  });
  const tickContainer = new Object3D();

  // compute positions: start after half a gap, then every (text segment + gap)
  let cursor = -textWidth / 2 + TICK_GAP / 2;
  const segmentLength = (textWidth + TICK_GAP) / config.textContent.length;

  for (let i = 0; i < config.textContent.length; i++) {
    const tick = new Mesh(tickGeo, tickMat);
    tick.position.set(cursor, 0, 0.002);
    tickContainer.add(tick);
    cursor += segmentLength + TICK_GAP;
  }

  // duplicate ticks for the cloned strip
  const tickClone = tickContainer.clone();
  tickClone.position.x += textWidth;
  root.add(tickContainer);
  root.add(tickClone);

  // ----- apply cinematic primitives -----------------------------------------
  if (Array.isArray(config.cinematicPrimitives)) {
    for (const prim of config.cinematicPrimitives) {
      const fn = ctx.primitives[prim.name];
      if (typeof fn === "function") {
        fn(root, prim.params);
      }
    }
  }

  // ----- animation (fallback if primitive does not move) --------------------
  // The fly-through primitive should handle constant motion, but we add a safety
  // GSAP ticker that updates the x position based on elapsed time.
  const speed = 0.4; // units per second (leftward)
  const loopLength = textWidth; // length of a single strip
  const tl = gsap.timeline({ repeat: -1, paused: false });
  tl.to(
    root.position,
    {
      x: `-=${loopLength}`,
      duration: loopLength / speed,
      ease: "none",
    },
    0
  );

  // ----- cleanup ------------------------------------------------------------
  root.userData.handlers = {}; // no interactive handlers for this element
  root.userData.cleanup = () => {
    tl.kill();
    planeGeo.dispose();
    baseMat.dispose();
    tickGeo.dispose();
    tickMat.dispose();
    if (textMesh.geometry) textMesh.geometry.dispose();
    if (textMesh.material) textMesh.material.dispose();
    if (textClone.geometry) textClone.geometry.dispose();
    if (textClone.material) textClone.material.dispose();
    // dispose any textures we created (font atlas is shared, do not dispose)
  };

  return root;
}
